cert={i:np.array(u,dtype=np.int64) for i,u in zip(ids,us)}
wd=np.array([w for w in product(range(6),repeat=6) if all(sum(t//2==j for t in w)==2 for j in range(3))],np.int16)
pr=[(i,j) for i in range(6) for j in range(i+1,6)];rows=np.array([36*z+6*wd[:,i]+wd[:,j] for z,(i,j) in enumerate(pr)],np.int16).T
rhs=[2-int(a//2==b//2) for _ in pr for a in range(6) for b in range(6)]
good=[];stats=Counter()
for idx,h in enumerate(gg):
 if sum(x*x for v in h for x in v)%5:stats['norm']+=1;continue
 ok=sum(np.array(alphabet(f))[wd[:,j]] for j,f in enumerate(h))%5==0;z=rows[ok]
 if np.bincount(z.ravel(),minlength=540).min()==0:stats['empty']+=1;continue
 if idx in cert:
  u=cert[idx];assert u.shape==(540,) and np.max(np.abs(u))<=2522
  assert int(u@rhs)<0 and np.min(u[z].sum(1))>=0;stats['strict']+=1
 else:good.append(idx)
assert stats==dict(norm=896,empty=23,strict=169) and len(good)==50
base=[gg[z] for z in good]


# Base-8 count-encodings of multisets on twelve signed triple types, no carries through size six.
powers={h:8**j for j,h in enumerate(T)}
multi=set()
for hs in base:
 for pi in permutations(range(3)):
  for s in (1,2):
   w=[powers[can(tuple(s*h[k]%5 for k in pi))] for h in hs];sub={0}
   for a in w:sub|={x+a for x in sub}
   multi|=sub
full=[h for a,b in product(range(5),repeat=2) if a or b for h in [(a,b,(-a-b)%5)]]
choices={h:[b for b in full if (h[0]*b[1]-h[1]*b[0])%5] for h in T}
def contrib(a,b):return tuple(powers[can(tuple((u*t+v)%5 for u,v in zip(a,b)))] for t in range(5))
C={h:[(b,contrib(h,b)) for b in choices[h]] for h in T}
from time import monotonic
start=monotonic();ct=Counter();valid=Counter()


def f2(z):
 bas={}
 for w in z:
  v=sum(1<<int(i) for i in w)
  while v:
   j=v.bit_length()-1
   if j in bas:v^=bas[j]
   else:bas[j]=v;break
 rr=sum((v%2)<<i for i,v in enumerate(rhs))
 while rr and rr.bit_length()-1 in bas:rr^=bas[rr.bit_length()-1]
 return not rr
status=Counter();surv=[]
def dfs(a,d,g,path):
 ct[d]+=1
 if d==6:
  vv=(sum(cost[j,b] for j,b in enumerate(path))%5==0);z=Z[vv]
  if np.bincount(z.ravel(),minlength=540).min()==0:status['miss']+=1;return
  if not f2(z):status['parity']+=1;return
  status['survive']+=1;surv.append((a,tuple(path)));return
 for b,v in C[a[d]]:
  x=tuple(i+j for i,j in zip(g,v))
  if all(y in multi for y in x):dfs(a,d+1,x,path+[b])
for i,u in zip(good,base):
 v0=(sum(np.array(alphabet(h))[wd[:,j]] for j,h in enumerate(u))%5==0)
 V=wd[v0];Z=rows[v0];cost={(j,b):np.array(alphabet(b),np.int16)[V[:,j]] for j in range(6) for b in full}
 b,v=C[u[0]][0];dfs(u,1,v,[b])
assert status=={'miss':1972,'parity':4223,'survive':81} and ct[6]==6276

def pkey(a,b):
 ans=[]
 for pi in permutations(range(3)):
  mats=[np.array([[h[pi[w]],k[pi[w]]] for w in range(2)],int) for h,k in zip(a,b)]
  for M in mats:
   J=int(M[0,0]*M[1,1]-M[0,1]*M[1,0])%5
   A=(np.array([[M[1,1],-M[0,1]],[-M[1,0],M[0,0]]])*pow(int(J),-1,5))%5
   t=[tuple((m@A%5).ravel()) for m in mats];ans.append(tuple(sorted(min(v,tuple(-x%5 for x in v)) for v in t)))
 return min(ans)
orbs={}
for a,b in surv:orbs.setdefault(pkey(a,b),(a,b))
assert len(orbs)==2

Examples=(
 ( ((0,1,4),(0,1,4),(0,1,4),(0,2,3),(0,2,3),(0,2,3)), ((1,0,4),(2,0,3),(3,0,2),(1,0,4),(2,0,3),(4,0,1)) ),
 ( ((0,1,4),(0,1,4),(1,0,4),(1,1,3),(1,3,1),(1,4,0)), ((1,0,4),(4,1,0),(2,1,2),(1,2,2),(1,2,2),(2,2,1)) ) )

assert {pkey(a,b) for a,b in Examples}==set(orbs)
counts=[]
for a,b in Examples:
 ok=(sum(np.array(alphabet(h))[wd[:,j]] for j,h in enumerate(a))%5==0)&(sum(np.array(alphabet(h))[wd[:,j]] for j,h in enumerate(b))%5==0)
 ww=wd[ok];zz=rows[ok]
 A=np.zeros((540,len(zz)),np.int8);A[zz,np.arange(len(zz))[:,None]]=1
 r=np.array(rhs)
 req=r.tolist();dom=[sum(1<<int(k) for k in np.flatnonzero(col)) for col in A]
 req1=sum(1<<j for j,t in enumerate(r) if t==1)
 cf=[]
 for j,w in enumerate(ww):
  cf.append(sum(1<<int(i) for i in np.flatnonzero((ww==w).sum(1)>=3)))
 nodes=0
 def go(available,nleft):
  global nodes
  nodes+=1
  if nleft==0:return 1
  best=-1;bc=999;opts=0
  for j,need in enumerate(req):
   if not need:continue
   cand=available&dom[j];cnt=cand.bit_count()
   if cnt<need:return 0
   if cnt<bc:bc=cnt;best=j;opts=cand
  while opts:
   bt=opts&-opts;opts^=bt;k=bt.bit_length()-1;valid=available&~cf[k];available^=bt
   for j in zz[k]:
    req[j]-=1
    if req[j]==0:valid&=~dom[j]
   ans=go(valid,nleft-1)
   for j in zz[k]:req[j]+=1
   if ans:return ans
  return 0
 assert go((1<<len(zz))-1,60)==0
 counts.append(nodes)
assert counts==[4,22]
print('1138 full-support shapes; 50 retained. Of 6276 potential planes, 81 pass the pair and parity screens; their 2 orbits fail exact cover in 4 and 22 nodes.')
